class Solution { static const long long MOD=1000000007;long long power(long long base,long long exponent){long long result=1;while(exponent){if(exponent&1)result=result*base%MOD;base=base*base%MOD;exponent>>=1;}return result;}public: int minNonZeroProduct(int p){long long maximum=(power(2,p)-1+MOD)%MOD,exponent=(1LL<<(p-1))-1;return maximum*power((maximum-1+MOD)%MOD,exponent)%MOD;} };
